# Redraws the app's emoji as soft, glossy painted icons (same renderer and look as the item sprites in make_items_soft.py).
# Writes www/assets/ico/<name>.png, plus tools/icons.js (emoji -> icon map used to swap emoji for these pictures).
# usage: python3 make_icons_soft.py [name,name,...]
import json, math, os, subprocess, sys, tempfile
