from make_items_soft import gear, star4, star5, circ, ell, rr, daisy, G, L, F, W, APPLE, TICKET, gift, PAGE, ITEMS
OUT = os.path.join(HERE, '..', 'www', 'assets', 'ico'); os.makedirs(OUT, exist_ok=True)

def poly(pts): return 'M' + ' L'.join('%.1f %.1f' % p for p in pts) + ' Z'
def rot(pts, cx, cy, a):
    c, s = math.cos(a), math.sin(a); return [(cx + (x - cx) * c - (y - cy) * s, cy + (x - cx) * s + (y - cy) * c) for x, y in pts]
def bar(x1, y1, x2, y2, w):  # a thick straight bar from (x1,y1) to (x2,y2) as a polygon
    a = math.atan2(y2 - y1, x2 - x1); nx, ny = -math.sin(a) * w / 2, math.cos(a) * w / 2
    return poly([(x1 + nx, y1 + ny), (x2 + nx, y2 + ny), (x2 - nx, y2 - ny), (x1 - nx, y1 - ny)])
def starN(cx, cy, R, r, n, phase=0):
    return poly([(cx + (R if i % 2 == 0 else r) * math.sin(phase + i * math.pi / n), cy - (R if i % 2 == 0 else r) * math.cos(phase + i * math.pi / n)) for i in range(2 * n)])
def heart(cx, cy, s):
    return 'M%.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f Z' % (
        cx, cy + s * .9, cx - s * .2, cy + s * .7, cx - s, cy + s * .2, cx - s, cy - s * .25, cx - s, cy - s * .8, cx - s * .2, cy - s * .9, cx, cy - s * .45,
        cx + s * .2, cy - s * .9, cx + s, cy - s * .8, cx + s, cy - s * .25, cx + s, cy + s * .2, cx + s * .2, cy + s * .7, cx, cy + s * .9)
def zee(x, y, s): return poly([(x, y), (x + s, y), (x + s, y + .24 * s), (x + .38 * s, y + .76 * s), (x + s, y + .76 * s), (x + s, y + s), (x, y + s), (x, y + .76 * s), (x + .62 * s, y + .24 * s), (x, y + .24 * s)])
def face(col, *extra): return [(G, circ(128, 130, 98), col), *extra]
EYES = [(F, ell(94, 112, 11, 15), '#3a2b2b'), (F, ell(162, 112, 11, 15), '#3a2b2b')]
BLUSH = [(F, ell(74, 150, 15, 8), '#ff9fb2'), (F, ell(182, 150, 15, 8), '#ff9fb2')]
def tkt(col, stub, mark, edge=None): return [(G, TICKET, col), (L, 'M170 88 L170 168', edge or col, 4, '8 7'), (F, rr(56, 106, 96, 44, 12), stub), *mark]
def book(x, y, w, h, col, page='#fff6e6'): return [(G, rr(x, y, w, h, 8), col), (F, rr(x + w - 14, y + 6, 10, h - 12, 3), page)]
def pokeball(cx, cy, r): return [(G, circ(cx, cy, r), '#f4f6fb'), (G, 'M%.1f %.1f A%.1f %.1f 0 0 1 %.1f %.1f Z' % (cx - r, cy, r, r, cx + r, cy), '#ef4b4b'), (L, 'M%.1f %.1f L%.1f %.1f' % (cx - r, cy, cx + r, cy), '#3a3a4a', max(3, r * .14)), (F, circ(cx, cy, r * .3), '#ffffff')]
def cloud(cx, cy, s, col): return [(G, 'M%.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f Z' % (
    cx - s, cy + s * .45, cx - s * 1.35, cy + s * .4, cx - s * 1.3, cy - s * .35, cx - s * .8, cy - s * .3, cx - s * .7, cy - s * 1.0, cx + s * .2, cy - s * 1.15, cx + s * .35, cy - s * .45,
    cx + s * .9, cy - s * .8, cx + s * 1.45, cy - s * .2, cx + s * 1.05, cy + s * .45, cx + s * .5, cy + s * .62, cx - s * .5, cy + s * .62, cx - s, cy + s * .45), col)]

