def main():
    from PIL import Image
    ONLY = set(sys.argv[1].split(',')) if len(sys.argv) > 1 else None
    names = [n for n in ICONS if not ONLY or n in ONLY]
    data = {n: [list(s) for s in ICONS[n][1]] for n in names}
    tmp = tempfile.mkdtemp(); html = os.path.join(tmp, 'ico.html')
    open(html, 'w').write(PAGE.replace('Object.entries(ITEMS)', 'Object.entries(' + json.dumps(data) + ')'))
    js = os.path.join(tmp, 'shot.js')
    open(js, 'w').write("""const { chromium } = require('/home/claude/.npm-global/lib/node_modules/playwright');
(async () => { const b = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium-1194/chrome-linux/chrome', args: ['--no-sandbox'] });
 const p = await b.newPage(); await p.goto('file://%s'); await p.waitForTimeout(300); const names = %s;
 for (const n of names) await p.locator('#' + n).screenshot({ path: '%s/' + n + '.png', omitBackground: true });
 await b.close() })();""" % (html, json.dumps(names), tmp))
    subprocess.run(['node', js], check=True)
    for n in names:
        im = Image.open(os.path.join(tmp, n + '.png')).convert('RGBA'); bb = im.getchannel('A').point(lambda a: 255 if a > 8 else 0).getbbox()
        im = im.crop((max(0, bb[0] - 4), max(0, bb[1] - 4), min(im.width, bb[2] + 4), min(im.height, bb[3] + 4)))
        s = max(im.size); sq = Image.new('RGBA', (s, s)); sq.paste(im, ((s - im.width) // 2, (s - im.height) // 2))   # square, so every icon sits on the same box
        sq = sq.resize((128, 128), Image.LANCZOS); sq.save(os.path.join(OUT, n + '.png'), optimize=True)
    emap = {}
    for n, (ems, _) in ICONS.items():
        for e in ems: emap[e] = n
    js_out = ('// ===================== SOFT ICONS =====================\n'
              '// Every emoji listed here is shown as a soft painted icon (assets/ico, drawn by tools/make_icons_soft.py) instead of the system emoji.\n'
              'const ICO_MAP=' + json.dumps(emap, ensure_ascii=False, separators=(',', ':')) + ';\n')
    open(os.path.join(HERE, 'icons_map.js'), 'w').write(js_out)
    print(len(names), 'icons;', len(emap), 'emoji mapped')
if __name__ == '__main__': main()
